# burst detection core (simplified)
def detect_bursts(events, gap_ms, min_tokens):
    bursts = []
    cur = None
    for e in events:
        if cur is None:
            cur = e.copy()
            continue
        if e['ts'] - cur['last_ts'] <= gap_ms:
            cur = merge(cur, e)
        else:
            if cur['tokens'] >= min_tokens:
                bursts.append(cur)
            cur = e.copy()
    return bursts
